from pathlib import Path
import subprocess,sys,json,hashlib
r=Path(__file__).resolve().parents[1]
inc=(r/"tests/cpu19_xml.inc").read_text().split("static void cpu19_install")[0]
pre='#include <stdlib.h>\n#include <stdio.h>\n#include <stdint.h>\ntypedef unsigned u32;typedef unsigned long long u64;\n#define CHECK(x) do{if(!(x))exit(__LINE__);}while(0)\n'
post='\nstatic int frees,visits,order[100],fallback;\nstatic void __attribute__((ms_abi)) del(void*p){frees++;free(p);}\nstatic void __attribute__((ms_abi)) original(void*p){fallback++;}\ntypedef struct Obj{void**vt;int id;void*head;u64 count;}Obj;\nstatic void* __attribute__((ms_abi)) destroy(void*p,u32 flags){Obj*o=p;CHECK(flags==1);order[visits++]=o->id;cpu19_clear(&o->head);CHECK(o->count==0);del(o->head);del(o);return p;}\nstatic void*vt[1]={(void*)destroy};\nstatic Obj*make(int id){Obj*o=calloc(1,sizeof(*o));o->vt=vt;o->id=id;void**h=calloc(3,sizeof(void*));h[0]=h;h[1]=h;o->head=h;return o;}\nstatic void add(Obj*p,Obj*c){void**h=p->head;void**n=calloc(3,sizeof(void*));void**last=h[1];n[0]=h;n[1]=last;n[2]=c;last[0]=n;h[1]=n;p->count++;}\nint main(){cpu19Delete=del;cpu19Original=original;Obj*root=make(0);void*sentinel=root->head;cpu19_clear(&root->head);CHECK(root->head==sentinel&&root->count==0&&frees==0&&visits==0);Obj*a=make(1),*b=make(2);add(a,make(3));add(root,a);add(root,b);cpu19_clear(&root->head);CHECK(root->head==sentinel&&root->count==0);CHECK(visits==3&&order[0]==1&&order[1]==3&&order[2]==2&&frees==9);CHECK(((void**)sentinel)[0]==sentinel&&((void**)sentinel)[1]==sentinel);cpu19_clear_hook(&root->head);CHECK(fallback==1);del(root->head);del(root);CHECK(frees==11);puts("PASS empty/nested ordered destruction, exact frees, retained empty sentinel, unrelated caller fallback");}\n'
b=r/'build/cpu19-unit';b.mkdir(exist_ok=True);(b/'test.c').write_text(pre+inc+post)
subprocess.run([sys.argv[1],'cc','-O2',str(b/'test.c'),'-o',str(b/'test.exe')],check=True)
x=subprocess.run([str(b/'test.exe')],capture_output=True,text=True);print(x.stdout+x.stderr)
(r/'audit/cpu19-unit.json').write_text(json.dumps(dict(scope='Compiled candidate helper, synthetic nested XML-style ownership graph; not native parser equivalence',exit=x.returncode,output=x.stdout+x.stderr,source_sha256=hashlib.sha256((r/'tests/cpu19_xml.inc').read_bytes()).hexdigest()),indent=2));raise SystemExit(x.returncode)
